	// Empty results are an empty array with a null cursor.
	page := decodeLogPage(t, getLogs(t, h, "q=absent"))
	if page.Entries == nil || len(page.Entries) != 0 || page.NextCursor != nil {
		t.Fatalf("empty page = %+v", page)
